321	pub fn load_explicit(p: &str) -> Result<Config, CfgErr> {
322	    let text = std::fs::read_to_string(p).map_err(|e| (p.to_string(), format!("failed to read config: {}", e)))?;
323	    let dir = std::fs::canonicalize(p)
324	        .ok()
325	        .and_then(|c| c.parent().map(|x| x.to_path_buf()))
326	        .unwrap_or_default();
327	    parse_config(&text, &dir).map_err(|m| (p.to_string(), m))
328	}
