330	/// Find the nearest yamark.toml from the file's directory upward.
331	pub fn discover(file: &Path) -> Result<Option<Config>, CfgErr> {
332	    let abs = if file.is_absolute() { file.to_path_buf() } else { std::env::current_dir().unwrap_or_default().join(file) };
333	    let mut dir = abs.parent().map(|p| p.to_path_buf());
334	    while let Some(d) = dir {
335	        let cand = d.join("yamark.toml");
336	        if cand.is_file() {
337	            let canon = std::fs::canonicalize(&cand).unwrap_or(cand.clone());
338	            let shown = canon.to_string_lossy().into_owned();
339	            let text = std::fs::read_to_string(&cand).map_err(|e| (shown.clone(), format!("failed to read config: {}", e)))?;
340	            let cdir = canon.parent().map(|x| x.to_path_buf()).unwrap_or_default();
341	            return parse_config(&text, &cdir).map(Some).map_err(|m| (shown, m));
342	        }
343	        dir = d.parent().map(|p| p.to_path_buf());
344	    }
345	    Ok(None)
346	}

