 12	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
 13	pub enum FileKind {
 14	    Yaml,
 15	    Markdown,
 16	    Python,
 17	    R,
 18	}
 19	
 20	pub fn detect_kind(path: &str) -> Option<FileKind> {
 21	    let name = Path::new(path).file_name()?.to_string_lossy().into_owned();
 22	    let dot = name.rfind('.')?;
 23	    if dot == 0 {
 24	        return None;
 25	    }
 26	    let ext = name[dot + 1..].to_ascii_lowercase();
 27	    match ext.as_str() {
 28	        "yaml" | "yml" => Some(FileKind::Yaml),
 29	        "md" | "qmd" | "rmd" => Some(FileKind::Markdown),
 30	        "py" => Some(FileKind::Python),
 31	        "r" => Some(FileKind::R),
 32	        _ => None,
 33	    }
 34	}
