 36	#[derive(Debug, Clone)]
 37	pub struct Diagnostic {
 38	    pub line: usize,
 39	    pub col: usize,
 40	    pub msg: String,
 41	}
 42	
 43	impl Diagnostic {
 44	    pub fn new(line: usize, col: usize, msg: impl Into<String>) -> Self {
 45	        Diagnostic { line, col, msg: msg.into() }
 46	    }
 47	}
 48	
 49	pub struct FormatOutcome {
 50	    pub text: String,
 51	    pub notes: Vec<Diagnostic>,
 52	}
 53	
 54	/// Format a whole file's text according to its kind.
 55	pub fn format_text(kind: FileKind, text: &str, opts: &Options) -> Result<FormatOutcome, Diagnostic> {
 56	    let mut notes = Vec::new();
 57	    // A UTF-8 byte-order mark is set aside while formatting; it still counts as a
 58	    // column of the first line. A BOM-prefixed YAML file is formatted only when it
 59	    // opens with a fmt directive and is otherwise kept as written, which is an error
 60	    // if it has directives elsewhere.
 61	    if let Some(body) = text.strip_prefix('\u{feff}') {
 62	        if kind == FileKind::Yaml {
 63	            match bom_yaml_mode(body) {
 64	                Some(true) => {}
 65	                Some(false) => return Ok(FormatOutcome { text: text.to_string(), notes }),
 66	                None => return Err(Diagnostic::new(1, 1, "formatting this BOM-prefixed YAML root is unsupported")),
 67	            }
 68	        }
 69	        let shift = |mut d: Diagnostic| {
 70	            if d.line == 1 {
 71	                d.col += 1;
 72	            }
 73	            d
 74	        };
 75	        return match format_text(kind, body, opts) {
 76	            Ok(mut o) => {
 77	                o.text.insert(0, '\u{feff}');
 78	                o.notes = o.notes.into_iter().map(shift).collect();
 79	                Ok(o)
 80	            }
 81	            Err(d) => Err(shift(d)),
 82	        };
 83	    }
 84	    let (normalized, eol) = normalize_eol(text);
 85	    crate::markdown::take_fragment_error();
 86	    let out = match kind {
 87	        FileKind::Yaml => crate::yaml::format_yaml_file(&normalized, opts, &mut notes)?,
 88	        FileKind::Markdown => crate::markdown::format_markdown_file(&normalized, opts, &mut notes)?,
 89	        FileKind::Python => crate::source::format_source_file(&normalized, opts, false, &mut notes)?,
 90	        FileKind::R => crate::source::format_source_file(&normalized, opts, true, &mut notes)?,
 91	    };
 92	    // An invalid directive in embedded Markdown fails the file.
 93	    if let Some(d) = crate::markdown::take_fragment_error() {
 94	        return Err(d);
 95	    }
 96	    let out = if text.contains("\r\n") && text.replace("\r\n", "").contains('\n') {
 97	        restore_mixed_eol(text, &normalized, &out, kind == FileKind::Markdown, eol)
 98	    } else {
 99	        restore_eol(&out, eol)
100	    };
101	    Ok(FormatOutcome { text: out, notes })
102	}
