104	/// Whether a BOM-prefixed YAML file is formatted (`Some(true)`: it opens with a fmt
105	/// directive), kept as written (`Some(false)`: it has no directives, or it would be
106	/// kept as written anyway) or rejected.
107	fn bom_yaml_mode(body: &str) -> Option<bool> {
108	    let is_directive = |c: &str| c.strip_prefix('#').is_some_and(|r| r.trim_start().starts_with("fmt:"));
109	    let lines: Vec<&str> = body.lines().collect();
110	    if lines.first().is_some_and(|l| is_directive(l.trim())) {
111	        return Some(true);
112	    }
113	    // Indentation of the line holding an open block scalar header.
114	    let mut block: Option<usize> = None;
115	    for l in &lines {
116	        let ind = l.len() - l.trim_start().len();
117	        if let Some(p) = block {
118	            if l.trim().is_empty() || ind > p {
119	                continue;
120	            }
121	            block = None;
122	        }
123	        let code = match yaml_comment_start(l) {
124	            Some(c) => {
125	                if is_directive(&l[c..]) {
126	                    let (normalized, _) = normalize_eol(body);
127	                    return crate::yaml::parser::Parser::new(&normalized).parse_stream().is_err().then_some(false);
128	                }
129	                &l[..c]
130	            }
131	            None => l,
132	        };
133	        let last = code.split_whitespace().last().unwrap_or("");
134	        let header = last.strip_prefix(['|', '>']).is_some_and(|r| r.len() <= 2 && r.chars().all(|c| matches!(c, '+' | '-' | '1'..='9')));
135	        if header {
136	            block = Some(ind);
137	        }
138	    }
139	    Some(false)
140	}
141	
142	/// Byte offset of a comment on a YAML line, skipping quoted text on that line.
143	fn yaml_comment_start(l: &str) -> Option<usize> {
144	    let mut quote: Option<char> = None;
145	    let mut prev = ' ';
146	    let mut chars = l.char_indices().peekable();
147	    while let Some((i, c)) = chars.next() {
148	        match quote {
149	            Some('"') if c == '\\' => {
150	                chars.next();
151	            }
152	            Some(q) if c == q => {
153	                if q == '\'' && chars.peek().is_some_and(|&(_, n)| n == '\'') {
154	                    chars.next();
155	                } else {
156	                    quote = None;
157	                }
158	            }
159	            Some(_) => {}
160	            None if c == '#' && prev.is_whitespace() => return Some(i),
161	            None if (c == '"' || c == '\'') && (prev.is_whitespace() || "[{,:-".contains(prev)) => quote = Some(c),
162	            None => {}
163	        }
164	        prev = c;
165	    }
166	    None
167	}
