169	#[derive(Clone, Copy, PartialEq, Eq)]
170	pub enum Eol {
171	    Lf,
172	    CrLf,
173	    Cr,
174	}
175	
176	pub fn normalize_eol(text: &str) -> (String, Eol) {
177	    if !text.contains('\r') {
178	        return (text.to_string(), Eol::Lf);
179	    }
180	    let crlf = text.matches("\r\n").count();
181	    let lone_cr = text.matches('\r').count() - crlf;
182	    let lf = text.matches('\n').count() - crlf;
183	    let eol = if crlf >= lf && crlf >= lone_cr {
184	        Eol::CrLf
185	    } else if lone_cr > lf && lone_cr > crlf {
186	        Eol::Cr
187	    } else {
188	        Eol::Lf
189	    };
190	    let s = text.replace("\r\n", "\n").replace('\r', "\n");
191	    (s, eol)
192	}
193	
194	/// Line endings for a file mixing CRLF and LF lines: an output line takes the
195	/// ending of the source line it comes from. Lines formatted together take the
196	/// ending of the first source line among them, or in Markdown of the last one
197	/// (table rows count as formatted together). Lines are matched through their
198	/// words.
199	fn restore_mixed_eol(text: &str, normalized: &str, out: &str, markdown: bool, eol: Eol) -> String {
200	    let src_lines: Vec<&str> = normalized.strip_suffix('\n').unwrap_or(normalized).split('\n').collect();
201	    let raw_lines: Vec<&str> = text.split('\n').collect();
202	    let crlf: Vec<bool> = (0..src_lines.len()).map(|i| raw_lines.get(i).is_some_and(|l| l.ends_with('\r'))).collect();
203	    let body = out.strip_suffix('\n');
204	    let out_lines: Vec<&str> = body.unwrap_or(out).split('\n').collect();
205	    let (n, m) = (src_lines.len(), out_lines.len());
206	    // Words are runs of letters and digits: formatting adds or drops quotes,
207	    // brackets, markers and spacing around them.
208	    let words = |l: &str| -> Vec<String> { l.split(|c: char| !c.is_alphanumeric()).filter(|t| !t.is_empty()).map(str::to_string).collect() };
209	    let src_tokens: Vec<(String, usize)> = src_lines.iter().enumerate().flat_map(|(i, l)| words(l).into_iter().map(move |t| (t, i))).collect();
210	    // Union-find over output lines (0..m) and source lines (m..m+n).
211	    let mut parent: Vec<usize> = (0..m + n).collect();
212	    fn find(p: &mut [usize], x: usize) -> usize {
213	        let mut r = x;
214	        while p[r] != r {
215	            r = p[r];
216	        }
217	        let mut y = x;
218	        while p[y] != r {
219	            let next = p[y];
220	            p[y] = r;
221	            y = next;
222	        }
223	        r
224	    }
225	    // Output tokens match source tokens in order: the next one, or a later one
226	    // followed by the same two tokens.
227	    let out_tokens: Vec<(String, usize)> = out_lines.iter().enumerate().flat_map(|(j, l)| words(l).into_iter().map(move |t| (t, j))).collect();
228	    let mut next = 0;
229	    for (p, (t, j)) in out_tokens.iter().enumerate() {
230	        let j = *j;
231	        let same = |k: usize, d: usize| match (src_tokens.get(k + d), out_tokens.get(p + d)) {
232	            (Some(a), Some(b)) => a.0 == b.0,
233	            (None, None) => true,
234	            _ => false,
235	        };
236	        let found = (next..(next + 64).min(src_tokens.len())).find(|&k| src_tokens[k].0 == *t && (k == next || (same(k, 1) && same(k, 2))));
237	        if let Some(k) = found {
238	            let i = src_tokens[k].1;
239	            let (a, b) = (find(&mut parent, j), find(&mut parent, m + i));
240	            parent[a] = b;
241	            next = k + 1;
242	        }
243	    }
244	    if markdown {
245	        for j in 1..m {
246	            if out_lines[j - 1].trim_start().starts_with('|') && out_lines[j].trim_start().starts_with('|') {
247	                let (a, b) = (find(&mut parent, j - 1), find(&mut parent, j));
248	                parent[a] = b;
249	            }
250	        }
251	    }
252	    // Folded block scalar content belongs together.
253	    {
254	        let mut j = 0;
255	        while j < m {
256	            let t = out_lines[j].trim_end();
257	            let header = t.rsplit(' ').next().is_some_and(|w| w.starts_with('>') && w[1..].chars().all(|c| matches!(c, '+' | '-' | '1'..='9')));
258	            if header {
259	                let ind = out_lines[j].len() - out_lines[j].trim_start().len();
260	                let mut k = j + 1;
261	                while k < m && (out_lines[k].trim().is_empty() || out_lines[k].len() - out_lines[k].trim_start().len() > ind) {
262	                    if k > j + 1 && !out_lines[k].trim().is_empty() {
263	                        let (a, b) = (find(&mut parent, j + 1), find(&mut parent, k));
264	                        parent[a] = b;
265	                    }
266	                    k += 1;
267	                }
268	                j = k;
269	                continue;
270	            }
271	            j += 1;
272	        }
273	    }
274	    // The first output line of each group.
275	    let mut first_out: Vec<Option<usize>> = vec![None; m + n];
276	    for j in 0..m {
277	        let r = find(&mut parent, j);
278	        first_out[r].get_or_insert(j);
279	    }
280	    // Source line range of each group.
281	    let mut range: Vec<Option<(usize, usize)>> = vec![None; m + n];
282	    for i in 0..n {
283	        let r = find(&mut parent, m + i);
284	        range[r] = Some(range[r].map_or((i, i), |(a, b)| (a.min(i), b.max(i))));
285	    }
286	    let mut res = String::new();
287	    let mut frontier = 0;
288	    for (j, l) in out_lines.iter().enumerate() {
289	        let r = find(&mut parent, j);
290	        // Lines without words consume source lines in order; a document marker
291	        // added between YAML documents takes the file's prevailing ending.
292	        let is_crlf = match range[r] {
293	            Some((a, b)) => {
294	                frontier = b + 1;
295	                // Markdown blocks end like their last line, a setext heading like its
296	                // underline; list items and quotes, like YAML nodes, like their first.
297	                let mut b = b;
298	                if markdown && l.trim_start().starts_with('#') && src_lines.get(b + 1).is_some_and(|u| !u.trim().is_empty() && u.trim().chars().all(|c| c == '=' || c == '-')) {
299	                    b += 1;
300	                    frontier = b + 1;
301	                }
302	                let lead = out_lines[first_out[r].unwrap_or(j)];
303	                let container = lead.trim_start().starts_with('>') || crate::markdown::block::list_marker(lead).is_some();
304	                let scalar = first_out[r].is_some_and(|f| {
305	                    f > 0 && out_lines[f - 1].trim_end().rsplit(' ').next().is_some_and(|w| w.starts_with('>') && w[1..].chars().all(|c| matches!(c, '+' | '-' | '1'..='9')))
306	                });
307	                crlf[if (markdown && !container) || scalar { b } else { a }]
308	            }
309	            None if !markdown && *l == "---" && src_lines.get(frontier).is_some_and(|s| s.trim_end() == "---") => {
310	                frontier += 1;
311	                crlf[frontier - 1]
312	            }
313	            None if !markdown && *l == "---" => eol == Eol::CrLf,
314	            // Inside output made from one source line, a line without words ends
315	            // like the rest.
316	            None if !l.trim().is_empty() && (j + 1..m).find_map(|k| range[find(&mut parent, k)]).is_some_and(|(a, _)| a < frontier) => {
317	                let (a, _) = (j + 1..m).find_map(|k| range[find(&mut parent, k)]).unwrap();
318	                crlf[a]
319	            }
320	            None => {
321	                // A blank line takes a nearby blank source line.
322	                if l.trim().is_empty() {
323	                    if let Some(k) = (frontier..(frontier + 3).min(n)).find(|&k| src_lines[k].trim().is_empty()) {
324	                        frontier = k;
325	                    }
326	                }
327	                frontier += 1;
328	                crlf.get((frontier - 1).min(n.saturating_sub(1))).copied().unwrap_or(false)
329	            }
330	        };
331	        res.push_str(l);
332	        if j + 1 < m || body.is_some() {
333	            res.push_str(if is_crlf { "\r\n" } else { "\n" });
334	        }
335	    }
336	    res
337	}
338	
339	pub fn restore_eol(text: &str, eol: Eol) -> String {
340	    match eol {
341	        Eol::Lf => text.to_string(),
342	        Eol::CrLf => text.replace('\n', "\r\n"),
343	        Eol::Cr => text.replace('\n', "\r"),
344	    }
345	}
346	
347	pub fn decode(bytes: &[u8]) -> Result<String, String> {
348	    if bytes.starts_with(&[0xFF, 0xFE]) || bytes.starts_with(&[0xFE, 0xFF]) {
349	        return Err("unsupported encoding: UTF-16 BOM".to_string());
350	    }
351	    match std::str::from_utf8(bytes) {
352	        Ok(s) => Ok(s.to_string()),
353	        Err(e) => Err(format!("invalid UTF-8: {}", e)),
354	    }
355	}
356	
357	fn base_options(m: &Matches) -> Options {
