  1	// YAML formatting.
  2	
  3	pub mod directive;
  4	pub mod emit;
  5	pub mod parser;
  6	pub mod scalar;
  7	
  8	use crate::format_cmd::Diagnostic;
  9	use crate::options::Options;
 10	use std::cell::RefCell;
 11	
 12	thread_local! {
 13	    /// Notes produced while formatting YAML (embedded formatter skips).
 14	    pub static YAML_NOTES: RefCell<Vec<Diagnostic>> = const { RefCell::new(Vec::new()) };
 15	    /// Counters from the most recent YAML emission.
 16	    pub static LAST_STATS: RefCell<Option<(emit::Stats, usize)>> = const { RefCell::new(None) };
 17	}
 18	
 19	fn count_nodes(n: &parser::Node) -> usize {
 20	    use parser::Kind;
 21	    1 + match &n.kind {
 22	        Kind::Map(es) => es.iter().map(|e| (if e.quirk == 0 { 1 } else { 0 }) + count_nodes(&e.value)).sum(),
 23	        Kind::Seq(items) => items.iter().map(|i| count_nodes(&i.value)).sum(),
 24	        Kind::FlowMap(es) | Kind::FlowSeq(es) => es
 25	            .iter()
 26	            .map(|e| e.key.as_ref().map(count_nodes).unwrap_or(0) + e.value.as_ref().map(count_nodes).unwrap_or(0))
 27	            .sum(),
 28	        _ => 0,
 29	    }
 30	}
 31	
 32	/// Format a YAML stream. Unparseable input is returned unchanged.
 33	pub fn format_yaml(src: &str, opts: &Options) -> Result<String, Diagnostic> {
 34	    if src.is_empty() {
 35	        return Ok(String::new());
 36	    }
 37	    let p = parser::Parser::new(src);
 38	    let line_starts = p.line_starts.clone();
 39	    let stream = match p.parse_stream() {
 40	        Ok(s) => s,
 41	        Err(e) => {
 42	            if std::env::var_os("YAMARK_DEBUG").is_some() {
 43	                let line = src[..e.pos.min(src.len())].matches('\n').count() + 1;
 44	                eprintln!("yaml parse error at line {}: {}", line, e.msg);
 45	            }
 46	            return Ok(src.to_string());
 47	        }
 48	    };
 49	    let dirs = directive::collect(src, &stream, &line_starts)?;
 50	    if dirs.skip_file {
 51	        return Ok(src.to_string());
 52	    }
 53	    let mut em = emit::Emitter::new(src, stream.line_kinds.clone(), line_starts, opts);
 54	    em.off_regions = dirs.off_regions.clone();
 55	    em.skip_lines = dirs.skip_lines.clone();
 56	    em.md_dirs = dirs.markdown.clone();
 57	    em.opt_dirs = dirs.options.clone();
 58	    em.emb_dirs = dirs.embedded.clone();
 59	    resolve_collection_dirs(src, &stream, &line_starts_of(src), &dirs, &mut em)?;
 60	    em.emit_stream(&stream);
 61	    if let Some(e) = em.error.take() {
 62	        return Err(e);
 63	    }
 64	    YAML_NOTES.with(|n| n.borrow_mut().extend(em.notes.drain(..)));
 65	    let stats = em.stats.clone();
 66	    let semantic: usize = stream.docs.iter().map(|d| d.root.as_ref().map(count_nodes).unwrap_or(0)).sum();
 67	    LAST_STATS.with(|s| *s.borrow_mut() = Some((stats, semantic)));
 68	    if let Some(&l) = em.skip_lines.iter().find(|l| !em.used_skips.contains(l)) {
 69	        let _ = l;
 70	        let (el, ec) = directive::eof_pos(src);
 71	        return Err(Diagnostic { line: el, col: ec, msg: "fmt: skip has no target".into() });
 72	    }
 73	    let mut out = em.out.join("\n");
 74	    if src.ends_with('\n') {
 75	        out.push('\n');
 76	    }
 77	    Ok(out)
 78	}
