124	/// Bind `fmt: table` and `fmt: compact` directives to the collections they target.
125	fn resolve_collection_dirs(src: &str, stream: &parser::Stream, ls: &[usize], dirs: &directive::Directives, em: &mut emit::Emitter) -> Result<(), Diagnostic> {
126	    use directive::Scope;
127	    let mut anchors = Vec::new();
128	    for d in &stream.docs {
129	        if let Some(r) = &d.root {
130	            dir_anchors(r, ls, &mut anchors);
131	        }
132	    }
133	    let eof = || directive::eof_pos(src);
134	    for &(line, collapse) in &dirs.tables {
135	        match anchors.iter().find(|a| a.2 && a.0 > line) {
136	            Some(a) => {
137	                em.table_targets.insert(a.1, collapse);
138	            }
139	            None => {
140	                let (l, c) = eof();
141	                return Err(Diagnostic { line: l, col: c, msg: "fmt: table has no target".into() });
142	            }
143	        }
144	    }
145	    for &(line, on, scope) in &dirs.compacts {
146	        if scope != Scope::Next {
147	            em.compact_scoped.push((line, on, scope));
148	            continue;
149	        }
150	        match anchors.iter().find(|a| a.0 > line) {
151	            Some(a) => {
152	                em.compact_override.insert(a.1, on);
153	            }
154	            None => {
155	                let (l, c) = eof();
156	                return Err(Diagnostic { line: l, col: c, msg: "fmt: compact has no target".into() });
157	            }
158	        }
159	    }
160	    Ok(())
161	}
162	
163	pub fn format_yaml_file(text: &str, opts: &Options, notes: &mut Vec<Diagnostic>) -> Result<String, Diagnostic> {
164	    YAML_NOTES.with(|n| n.borrow_mut().clear());
165	    LAST_STATS.with(|s| *s.borrow_mut() = None);
166	    let r = match format_json_lines(text, opts) {
167	        Some(out) => Ok(out),
168	        None => format_yaml(text, opts),
169	    };
170	    YAML_NOTES.with(|n| notes.extend(n.borrow_mut().drain(..)));
171	    if opts.diagnostics {
172	        if let Ok(out) = &r {
173	            let lines = if text.is_empty() { 0 } else { text.strip_suffix('\n').unwrap_or(text).split('\n').count() };
174	            let (st, sem) = LAST_STATS.with(|s| s.borrow().clone()).unwrap_or_default();
175	            let msg = format!(
176	                "yaml trace: source_scans=1 parse_passes=1 source_lines={} yaml_scanned_lines={} yaml_semantic_nodes={} planned_rendered_scalars={} planned_rendered_flow_collections={} planned_rendered_block_flow_collections={} emitted_bytes={} emitted_nodes={}",
177	                lines, lines, sem, st.scalars, st.flows, st.block_flows, out.len(), st.emitted_nodes
178	            );
179	            notes.push(Diagnostic { line: 1, col: 1, msg });
180	        }
181	    }
182	    r
183	}
184	
185	/// A stream of two or more one-line flow-mapping roots becomes a multi-document stream.
186	fn format_json_lines(text: &str, opts: &Options) -> Option<String> {
187	    let body = text.strip_suffix('\n').unwrap_or(text);
188	    let lines: Vec<&str> = body.split('\n').collect();
189	    if lines.len() < 2 {
190	        return None;
191	    }
192	    for l in &lines {
193	        let t = l.trim();
194	        if !t.starts_with('{') {
195	            return None;
196	        }
197	        let p = parser::Parser::new(t);
198	        let st = p.parse_stream().ok()?;
199	        if st.docs.len() != 1 || !st.docs[0].extra.is_empty() {
200	            return None;
201	        }
202	        match &st.docs[0].root {
203	            Some(n) if matches!(n.kind, parser::Kind::FlowMap(_)) && n.end_line == 0 => {}
204	            _ => return None,
205	        }
206	    }
207	    let mut out = String::new();
208	    let mut total = emit::Stats::default();
209	    let mut sem = 0;
210	    for l in &lines {
211	        out.push_str("---\n");
212	        let f = format_yaml(&format!("{}\n", l.trim_end()), opts).ok()?;
213	        if let Some((st, n)) = LAST_STATS.with(|s| s.borrow().clone()) {
214	            total.scalars += st.scalars;
215	            total.flows += st.flows;
216	            total.block_flows += st.block_flows;
217	            total.emitted_nodes += st.emitted_nodes;
218	            sem += n;
219	        }
220	        out.push_str(&f);
221	    }
222	    LAST_STATS.with(|s| *s.borrow_mut() = Some((total, sem)));
223	    if !text.ends_with('\n') {
224	        out.pop();
225	    }
226	    Some(out)
227	}

