 37	fn apply_template(base: &mut Vec<(String, String)>, t: &TemplateCfg) {
 38	    if let Some(r) = &t.replace {
 39	        *base = r.clone();
 40	    }
 41	    base.extend(t.add.iter().cloned());
 42	}
