 44	impl Config {
 45	    pub fn apply(&self, o: &mut Options, file: &Path) {
 46	        if let Some(w) = self.wrap {
 47	            o.wrap = w;
 48	        }
 49	        if let Some(t) = self.table_widths {
 50	            o.table_widths = t;
 51	        }
 52	        if let Some(c) = self.compact {
 53	            o.compact = c;
 54	        }
 55	        if let Some(h) = &self.hr {
 56	            o.hr_marker = h.clone();
 57	        }
 58	        apply_template(&mut o.templates.pairs, &self.template);
 59	        apply_template(&mut o.embedded_md_templates.pairs, &self.template);
 60	        // Path layers from shallowest to deepest.
 61	        let abs = std::fs::canonicalize(file).unwrap_or_else(|_| {
 62	            let p = if file.is_absolute() { file.to_path_buf() } else { std::env::current_dir().unwrap_or_default().join(file) };
 63	            p
 64	        });
 65	        let rel = abs.strip_prefix(&self.dir).map(|p| p.to_path_buf()).unwrap_or_default();
 66	        let mut layers: Vec<&(String, Option<TemplateCfg>, Option<TemplateCfg>)> = self
 67	            .paths
 68	            .iter()
 69	            .filter(|(k, _, _)| {
 70	                let kp = Path::new(k.trim_end_matches('/'));
 71	                rel.starts_with(kp)
 72	            })
 73	            .collect();
 74	        layers.sort_by_key(|(k, _, _)| Path::new(k).components().count());
 75	        for (_, t, em) in layers {
 76	            if let Some(t) = t {
 77	                apply_template(&mut o.templates.pairs, t);
 78	                apply_template(&mut o.embedded_md_templates.pairs, t);
 79	            }
 80	            if let Some(em) = em {
 81	                apply_template(&mut o.embedded_md_templates.pairs, em);
 82	            }
 83	        }
 84	    }
 85	}
