 87	type CfgErr = (String, String);
 88	
 89	fn parse_delims(v: &Value, name: &str) -> Result<Vec<(String, String)>, String> {
 90	    let arr = match v {
 91	        Value::Array(a) => a,
 92	        _ => return Err(format!("{} must be an array", name)),
 93	    };
 94	    let mut out = Vec::new();
 95	    for item in arr {
 96	        let t = match item {
 97	            Value::Table(t) => t,
 98	            _ => return Err(format!("{} entries must be tables", name)),
 99	        };
100	        for (k, _) in t {
101	            if k != "open" && k != "close" {
102	                return Err(format!("unknown {} key: {}", name, k));
103	            }
104	        }
105	        let open = match item.get("open") {
106	            Some(Value::Str(s)) => s.clone(),
107	            Some(_) => return Err(format!("{}.open must be a string", name)),
108	            None => return Err(format!("{}.open is required", name)),
109	        };
110	        let close = match item.get("close") {
111	            Some(Value::Str(s)) => s.clone(),
112	            Some(_) => return Err(format!("{}.close must be a string", name)),
113	            None => return Err(format!("{}.close is required", name)),
114	        };
115	        if open.is_empty() {
116	            return Err(format!("{}.open must not be empty", name));
117	        }
118	        if close.is_empty() {
119	            return Err(format!("{}.close must not be empty", name));
120	        }
121	        out.push((open, close));
122	    }
123	    Ok(out)
124	}
125	
126	fn parse_template(v: &Value, prefix: &str) -> Result<TemplateCfg, String> {
127	    let t = match v {
128	        Value::Table(t) => t,
129	        _ => return Err(format!("{} config must be a table", prefix)),
130	    };
131	    let mut cfg = TemplateCfg::default();
132	    for (k, val) in t {
133	        match k.as_str() {
134	            "add_delimiters" => cfg.add = parse_delims(val, &format!("{}.add_delimiters", prefix))?,
135	            "replace_delimiters" => cfg.replace = Some(parse_delims(val, &format!("{}.replace_delimiters", prefix))?),
136	            _ => return Err(format!("unknown template config key: {}.{}", prefix, k)),
137	        }
138	    }
139	    Ok(cfg)
140	}
