142	const SHORTHANDS: &[&str] = &[
143	    "ruff", "air", "mdformat", "prettier-json", "prettier-jsonc", "prettier-json5", "prettier-graphql", "prettier-css", "prettier-scss", "prettier-less", "prettier-postcss", "prettier-html", "prettier-js", "prettier-jsx", "prettier-ts", "prettier-tsx",
144	];
145	
146	fn parse_config(text: &str, dir: &Path) -> Result<Config, String> {
147	    let root = match crate::toml::parse(text) {
148	        Ok(v) => v,
149	        Err(e) => {
150	            let line_text = text.lines().nth(e.line.saturating_sub(1)).unwrap_or("");
151	            let caret = format!("{}{}", " ".repeat(e.col.saturating_sub(1)), "^".repeat(e.span.max(1)));
152	            let msg = e.msg.replace("\\n", "\n");
153	            let w = e.line.to_string().len();
154	            return Err(format!(
155	                "invalid yamark.toml: TOML parse error at line {}, column {}\n{} |\n{} | {}\n{} | {}\n{}\n",
156	                e.line,
157	                e.col,
158	                " ".repeat(w),
159	                e.line,
160	                line_text,
161	                " ".repeat(w),
162	                caret,
163	                msg
164	            ));
165	        }
166	    };
167	    let mut cfg = Config { dir: dir.to_path_buf(), ..Default::default() };
168	    let top = match &root {
169	        Value::Table(t) => t,
170	        _ => return Err("invalid yamark.toml".into()),
171	    };
172	    for (k, v) in top {
173	        match k.as_str() {
174	            "format" => {
175	                let t = match v {
176	                    Value::Table(t) => t,
177	                    _ => return Err("format config must be a table".into()),
178	                };
179	                for (fk, fv) in t {
180	                    match fk.as_str() {
181	                        "wrap" => match fv {
182	                            Value::Str(s) => match crate::options::parse_wrap(s) {
183	                                Some(w) => cfg.wrap = Some(w),
184	                                None => return Err("format.wrap must be none, paragraph, sentence, a positive integer, or sentence:<positive integer>".into()),
185	                            },
186	                            _ => return Err("format.wrap must be a string".into()),
187	                        },
188	                        "table_widths" => match fv {
189	                            Value::Str(s) if s == "fit" => cfg.table_widths = Some(TableWidths::Fit),
190	                            Value::Str(s) if s == "preserve" => cfg.table_widths = Some(TableWidths::Preserve),
191	                            _ => return Err("format.table_widths must be fit or preserve".into()),
192	                        },
193	                        "compact" => match fv {
194	                            Value::Bool(b) => cfg.compact = Some(*b),
195	                            _ => return Err("format.compact must be a boolean".into()),
196	                        },
197	                        "markdown_horizontal_rule" => match fv {
198	                            Value::Str(s) if s == "---" || s == "***" => cfg.hr = Some(s.clone()),
199	                            _ => return Err("format.markdown_horizontal_rule must be \"---\" or \"***\"".into()),
200	                        },
201	                        _ => return Err(format!("unknown format config key: format.{}", fk)),
202	                    }
203	                }
204	            }
205	            "template" => cfg.template = parse_template(v, "template")?,
206	            "embedded" => {
207	                let t = match v {
208	                    Value::Table(t) => t,
209	                    _ => return Err("embedded config must be a table".into()),
210	                };
211	                for (name, ev) in t {
212	                    if name.is_empty() || name.trim() != name {
213	                        return Err("embedded formatter names must be non-empty and trimmed".into());
214	                    }
215	                    if matches!(name.as_str(), "skip" | "skip file" | "off" | "on" | "table") {
216	                        return Err(format!("reserved fmt directive name: {}", name));
217	                    }
218	                    let et = match ev {
219	                        Value::Table(t) => t,
220	                        _ => return Err(format!("embedded.{} must be a table", name)),
221	                    };
222	                    let f = match ev.get("formatter") {
223	                        Some(f) => f,
224	                        None => return Err("embedded formatter entries must contain formatter".into()),
225	                    };
226	                    for (ek, _) in et {
227	                        if ek != "formatter" {
228	                            return Err(format!("unknown embedded config key: embedded.{}.{}", name, ek));
229	                        }
230	                    }
231	                    let fc = match f {
232	                        Value::Str(s) => {
233	                            if !SHORTHANDS.contains(&s.as_str()) {
234	                                return Err(format!("unknown embedded formatter shorthand: {}", s));
235	                            }
236	                            FormatterCfg::Builtin(s.clone())
237	                        }
238	                        Value::Table(ft) => {
239	                            for (fk, _) in ft {
240	                                if fk != "command" && fk != "path_suffix" {
241	                                    return Err(format!("unknown embedded formatter key: {}", fk));
242	                                }
243	                            }
244	                            let command: Vec<String> = match f.get("command") {
245	                                Some(Value::Array(a)) => {
246	                                    let mut v = Vec::new();
247	                                    for x in a {
248	                                        match x {
249	                                            Value::Str(s) => v.push(s.clone()),
250	                                            _ => return Err("embedded formatter command must be an array of strings".into()),
251	                                        }
252	                                    }
253	                                    v
254	                                }
255	                                Some(_) => return Err("embedded formatter command must be an array of strings".into()),
256	                                None => return Err("missing embedded formatter command".into()),
257	                            };
258	                            if command.is_empty() {
259	                                return Err("embedded formatter command must not be empty".into());
260	                            }
261	                            if !command.iter().any(|a| a == "{path}") || command.iter().any(|a| a != "{path}" && a.contains("{path}")) {
262	                                return Err("embedded formatter command must contain {path} as an argv item".into());
263	                            }
264	                            let path_suffix = match f.get("path_suffix") {
265	                                Some(Value::Str(s)) if !s.is_empty() => s.clone(),
266	                                Some(_) => return Err("embedded formatter path_suffix must not be empty".into()),
267	                                None => return Err("missing embedded formatter path_suffix".into()),
268	                            };
269	                            FormatterCfg::Custom { command, path_suffix }
270	                        }
271	                        _ => return Err("embedded formatter must be a string or table".into()),
272	                    };
273	                    cfg.embedded.push((name.clone(), fc));
274	                }
275	            }
276	            "paths" => {
277	                let t = match v {
278	                    Value::Table(t) => t,
279	                    _ => return Err("paths config must be a table".into()),
280	                };
281	                for (pk, pv) in t {
282	                    if pk.is_empty() {
283	                        return Err("path config keys must not be empty".into());
284	                    }
285	                    if pk.starts_with('/') || Path::new(pk).components().any(|c| matches!(c, std::path::Component::ParentDir)) {
286	                        return Err("path config keys must be relative and must not contain ..".into());
287	                    }
288	                    let pt = match pv {
289	                        Value::Table(t) => t,
290	                        _ => return Err(format!("paths.{} must be a table", pk)),
291	                    };
292	                    let mut tmpl = None;
293	                    let mut emb = None;
294	                    for (sk, sv) in pt {
295	                        match sk.as_str() {
296	                            "template" => tmpl = Some(parse_template(sv, &format!("paths.{}.template", pk))?),
297	                            "embedded_markdown" => {
298	                                let et = match sv {
299	                                    Value::Table(t) => t,
300	                                    _ => return Err(format!("paths.{}.embedded_markdown must be a table", pk)),
301	                                };
302	                                for (ek, ev) in et {
303	                                    if ek != "template" {
304	                                        return Err(format!("unknown path config key: paths.{}.embedded_markdown.{}", pk, ek));
305	                                    }
306	                                    emb = Some(parse_template(ev, &format!("paths.{}.embedded_markdown.template", pk))?);
307	                                }
308	                            }
309	                            _ => return Err(format!("unknown path config key: paths.{}.{}", pk, sk)),
310	                        }
311	                    }
312	                    cfg.paths.push((pk.clone(), tmpl, emb));
313	                }
314	            }
315	            _ => return Err(format!("unknown config key: {}", k)),
316	        }
317	    }
318	    Ok(cfg)
319	}
