 80	fn line_starts_of(src: &str) -> Vec<usize> {
 81	    let mut v = vec![0];
 82	    for (i, c) in src.bytes().enumerate() {
 83	        if c == b'\n' {
 84	            v.push(i + 1);
 85	        }
 86	    }
 87	    v
 88	}
