 90	fn coll_key(n: &parser::Node, ls: &[usize]) -> usize {
 91	    match &n.kind {
 92	        parser::Kind::Seq(items) => items.first().map(|i| ls[i.line] + i.col).unwrap_or(n.start),
 93	        _ => n.start,
 94	    }
 95	}
 96	
 97	/// Places that bind a pending collection directive, in document order:
 98	/// (line, collection key, is sequence). Every sequence item binds its sequence;
 99	/// a mapping entry binds its collection value.
100	fn dir_anchors(n: &parser::Node, ls: &[usize], out: &mut Vec<(usize, usize, bool)>) {
101	    use parser::Kind;
102	    match &n.kind {
103	        Kind::Map(es) => {
104	            for e in es {
105	                let v = &e.value;
106	                if matches!(v.kind, Kind::Map(_) | Kind::Seq(_) | Kind::FlowMap(_) | Kind::FlowSeq(_)) {
107	                    out.push((e.line, coll_key(v, ls), matches!(v.kind, Kind::Seq(_) | Kind::FlowSeq(_))));
108	                }
109	                dir_anchors(v, ls, out);
110	            }
111	        }
112	        Kind::Seq(items) => {
113	            let k = coll_key(n, ls);
114	            for it in items {
115	                out.push((it.line, k, true));
116	                dir_anchors(&it.value, ls, out);
117	            }
118	        }
119	        Kind::FlowSeq(_) => out.push((n.line, n.start, true)),
120	        _ => {}
121	    }
122	}
