 34	fn scan_python(src: &str) -> Tokens {
 35	    let b = src.as_bytes();
 36	    let mut i = 0;
 37	    let mut strings = Vec::new();
 38	    let mut comments = Vec::new();
 39	    while i < b.len() {
 40	        let c = b[i];
 41	        if c == b'#' {
 42	            comments.push(i);
 43	            while i < b.len() && b[i] != b'\n' {
 44	                i += 1;
 45	            }
 46	            continue;
 47	        }
 48	        if c == b'"' || c == b'\'' {
 49	            // Prefix letters before the quote.
 50	            let mut ps = i;
 51	            while ps > 0 && (b[ps - 1] as char).is_ascii_alphabetic() {
 52	                ps -= 1;
 53	            }
 54	            let prefix = src[ps..i].to_ascii_lowercase();
 55	            let valid_prefix = matches!(prefix.as_str(), "" | "r" | "u" | "b" | "f" | "br" | "rb" | "fr" | "rf" | "t" | "tr" | "rt");
 56	            // A prefix must not be part of a longer identifier.
 57	            let ps_ok = ps == 0 || !((b[ps - 1] as char).is_ascii_alphanumeric() || b[ps - 1] == b'_');
 58	            let (start, prefix) = if valid_prefix && ps_ok { (ps, prefix) } else { (i, String::new()) };
 59	            let raw = prefix.contains('r');
 60	            let triple = i + 2 < b.len() && b[i + 1] == c && b[i + 2] == c;
 61	            let q = c;
 62	            let content_start = if triple { i + 3 } else { i + 1 };
 63	            let is_close = |j: usize| b[j] == q && (!triple || (j + 2 < b.len() && b[j + 1] == q && b[j + 2] == q));
 64	            // A delimiter on the opening line closes the string; otherwise a triple-quoted
 65	            // string runs to the first closing delimiter that starts a line.
 66	            let mut found = None;
 67	            let mut j = content_start;
 68	            while j < b.len() && b[j] != b'\n' {
 69	                if b[j] == b'\\' && b.get(j + 1) != Some(&b'\n') {
 70	                    j += 2;
 71	                    continue;
 72	                }
 73	                if is_close(j) {
 74	                    found = Some(j);
 75	                    break;
 76	                }
 77	                j += 1;
 78	            }
 79	            if found.is_none() && triple {
 80	                let mut j = content_start;
 81	                while j < b.len() {
 82	                    if is_close(j) && closes_line_start(b, j) {
