691	fn project(v: &Value, trailing: &[String], has_comments: bool, leading: &[String], opts: &Options) -> String {
692	    let yaml_src = if has_comments {
693	        let mut lines = Vec::new();
694	        for c in leading {
695	            lines.push(format!("# {}", sanitize_comment(c)).trim_end().to_string());
696	        }
697	        block_text(v, 0, &mut lines);
698	        for c in trailing {
699	            lines.push(format!("# {}", sanitize_comment(c)).trim_end().to_string());
700	        }
701	        format!("{}\n", lines.join("\n"))
702	    } else {
703	        format!("{}\n", flow_text(v))
704	    };
705	    crate::yaml::format_yaml(&yaml_src, opts).unwrap_or(yaml_src)
706	}
