455	pub fn run_format(m: &Matches) -> i32 {
456	    if let Some(p) = m.value("stdin-file-path") {
457	        if !m.positionals.is_empty() {
458	            eprint!("error: --stdin-file-path cannot be used with PATHS\n");
459	            return 2;
460	        }
461	        if m.flag("check") || m.flag("diff") {
462	            eprint!("error: --stdin-file-path cannot be used with --check or --diff\n");
463	            return 2;
464	        }
465	        let p = p.to_string();
466	        return run_stdin(m, &p);
467	    }
468	    let check = m.flag("check");
469	    let diff_mode = m.flag("diff");
470	    let roots: Vec<String> = if m.positionals.is_empty() {
471	        vec![".".to_string()]
472	    } else {
473	        m.positionals.clone()
474	    };
475	    for r in &roots {
476	        if std::fs::symlink_metadata(r).is_err() && !Path::new(r).exists() {
477	            eprint!("{}:1:1: error: path does not exist\n", r);
478	            return 1;
479	        }
480	    }
481	    // Explicit config is loaded once up front.
482	    let explicit_cfg = if let Some(p) = m.value("config") {
483	        match config::load_explicit(p) {
484	            Ok(c) => Some(c),
485	            Err((p, msg)) => {
486	                eprint!("{}:1:1: error: {}\n", p, msg);
487	                return 1;
488	            }
489	        }
490	    } else {
491	        None
492	    };
493	    let mut files: Vec<PathBuf> = Vec::new();
494	    let mut seen: HashSet<PathBuf> = HashSet::new();
495	    let mut walker = Walker::new();
496	    for r in &roots {
497	        let p = Path::new(r);
498	        let list = if p.is_dir() { walker.walk(p) } else { vec![p.to_path_buf()] };
499	        for f in list {
500	            let key = std::fs::canonicalize(&f).unwrap_or_else(|_| f.clone());
501	            if seen.insert(key) {
502	                files.push(f);
503	            }
504	        }
505	    }
506	
507	    // Configurations are resolved for every selected file before any formatting.
508	    let mut configs: Vec<Option<config::Config>> = Vec::new();
509	    {
510	        let mut cache: std::collections::HashMap<PathBuf, Option<config::Config>> = std::collections::HashMap::new();
511	        for f in &files {
512	            if explicit_cfg.is_some() || detect_kind(&f.to_string_lossy()).is_none() {
513	                configs.push(None);
514	                continue;
515	            }
516	            let dir = f.parent().map(|p| p.to_path_buf()).unwrap_or_default();
517	            if let Some(c) = cache.get(&dir) {
518	                configs.push(c.clone());
519	                continue;
520	            }
521	            match config::discover(f) {
522	                Ok(c) => {
523	                    cache.insert(dir, c.clone());
524	                    configs.push(c);
525	                }
526	                Err((p, msg)) => {
527	                    eprint!("{}:1:1: error: {}\n", p, msg);
528	                    return 1;
529	                }
530	            }
531	        }
532	    }
533	    let mut scanned = 0usize;
534	    let mut formatted = 0usize;
535	    let mut unchanged = 0usize;
536	    let mut skipped = 0usize;
537	    let mut failed = 0usize;
538	    // (path, is_note, text)
539	    let mut msgs: Vec<(String, bool, String)> = Vec::new();
540	    let mut stdout = std::io::stdout();
541	    for (fi, f) in files.iter().enumerate() {
542	        scanned += 1;
543	        let display = f.to_string_lossy().into_owned();
544	        let kind = match detect_kind(&display) {
545	            Some(k) => k,
546	            None => {
547	                skipped += 1;
548	                continue;
549	            }
550	        };
551	        let cfg: Option<&config::Config> = if let Some(c) = &explicit_cfg { Some(c) } else { configs[fi].as_ref() };
552	        let bytes = match std::fs::read(f) {
553	            Ok(b) => b,
554	            Err(e) => {
555	                failed += 1;
556	                msgs.push((display.clone(), false, format!("{}:1:1: error: failed to read file: {}\n", display, io_error_text(&e))));
557	                continue;
558	            }
559	        };
560	        let text = match decode(&bytes) {
561	            Ok(t) => t,
562	            Err(e) => {
563	                failed += 1;
564	                msgs.push((display.clone(), false, format!("{}:1:1: error: failed to read file: {}\n", display, e)));
565	                continue;
566	            }
567	        };
568	        let opts = effective_options(m, cfg, f);
569	        match format_text(kind, &text, &opts) {
570	            Ok(out) => {
571	                for n in &out.notes {
572	                    msgs.push((display.clone(), true, print_diag(&display, n, "note")));
573	                }
574	                if out.text == text {
575	                    unchanged += 1;
576	                } else {
577	                    formatted += 1;
578	                    if diff_mode {
579	                        let d = diff::unified_diff(&text, &out.text, &display, &display);
580	                        let _ = stdout.write_all(d.as_bytes());
581	                    } else if !check {
582	                        if let Err(e) = std::fs::write(f, out.text.as_bytes()) {
583	                            failed += 1;
584	                            formatted -= 1;
585	                            msgs.push((display.clone(), false, format!("{}:1:1: error: failed to write file: {}\n", display, io_error_text(&e))));
586	                        }
587	                    }
588	                }
589	            }
590	            Err(d) => {
591	                failed += 1;
592	                msgs.push((display.clone(), false, print_diag(&display, &d, "error")));
593	            }
594	        }
595	    }
596	    let show_notes = m.flag("diagnostics") || failed > 0;
597	    msgs.sort_by(|a, b| a.0.cmp(&b.0));
598	    let mut messages = String::new();
599	    for (_, is_note, text) in &msgs {
600	        if *is_note && !show_notes {
601	            continue;
602	        }
603	        messages.push_str(text);
604	    }
605	    let _ = stdout.flush();
606	    let summary = format!(
607	        "{} files scanned, {} formatted, {} unchanged, {} skipped, {} failed\n",
608	        scanned, formatted, unchanged, skipped, failed
609	    );
610	    if check || diff_mode {
611	        eprint!("{}{}", summary, messages);
612	    } else {
613	        let _ = stdout.write_all(summary.as_bytes());
614	        let _ = stdout.flush();
615	        eprint!("{}", messages);
616	    }
617	    if failed > 0 {
618	        return 1;
619	    }
620	    if (check || diff_mode) && formatted > 0 {
621	        return 1;
622	    }
623	    0
624	}
