120	/// Whether only spaces or tabs precede position `p` on its line.
121	fn closes_line_start(b: &[u8], p: usize) -> bool {
122	    let mut k = p;
123	    while k > 0 && matches!(b[k - 1], b' ' | b'\t') {
124	        k -= 1;
125	    }
126	    k > 0 && b[k - 1] == b'\n'
127	}
