129	fn scan_r(src: &str) -> Tokens {
130	    let b = src.as_bytes();
131	    let mut i = 0;
132	    let mut strings = Vec::new();
133	    let mut comments = Vec::new();
134	    while i < b.len() {
135	        let c = b[i];
136	        if c == b'#' {
137	            comments.push(i);
138	            while i < b.len() && b[i] != b'\n' {
139	                i += 1;
140	            }
141	            continue;
142	        }
143	        if (c == b'r' || c == b'R') && i + 1 < b.len() && (b[i + 1] == b'"' || b[i + 1] == b'\'') && (i == 0 || !((b[i - 1] as char).is_ascii_alphanumeric() || b[i - 1] == b'.' || b[i - 1] == b'_')) {
144	            // Raw string r"---( ... )---"
145	            let q = b[i + 1];
146	            let mut j = i + 2;
147	            let ds = j;
148	            while j < b.len() && b[j] == b'-' {
149	                j += 1;
150	            }
151	            let dashes = j - ds;
152	            if j < b.len() && matches!(b[j], b'(' | b'[' | b'{') {
153	                let open = b[j];
154	                let close = match open {
155	                    b'(' => b')',
156	                    b'[' => b']',
157	                    _ => b'}',
158	                };
159	                let content_start = j + 1;
160	                let mut k = content_start;
161	                let mut found = None;
162	                while k < b.len() {
163	                    if b[k] == close {
164	                        let mut m = k + 1;
165	                        let mut d = 0;
166	                        while m < b.len() && b[m] == b'-' && d < dashes {
167	                            m += 1;
168	                            d += 1;
169	                        }
170	                        if d == dashes && m < b.len() && b[m] == q {
171	                            found = Some((k, m + 1));
172	                            break;
173	                        }
174	                    }
175	                    k += 1;
176	                }
177	                if let Some((ce, end)) = found {
178	                    strings.push(StrLit {
179	                        start: i,
180	                        quote_start: i + 1,
181	                        content_start,
182	                        content_end: ce,
183	                        end,
184	                        triple: false,
185	                        raw: true,
186	                        bytes: false,
187	                        fstring: false,
188	                        starts_nl: b.get(content_start) == Some(&b'\n'),
189	                        ml: src[content_start..ce].contains('\n'),
190	                    });
191	                    i = end;
192	                    continue;
193	                }
194	            }
195	        }
196	        if c == b'"' || c == b'\'' {
197	            // A quote opens a string running to the first later line that starts
198	            // with the same quote; scanning resumes on the line after it. Without
199	            // such a line the string must close on its own line.
200	            let q = c;
201	            let content_start = i + 1;
202	            let le = b[i..].iter().position(|&x| x == b'\n').map(|p| i + p).unwrap_or(b.len());
203	            let mut ml_end = None;
204	            let mut j = le;
205	            while j < b.len() {
206	                if b[j] == q && closes_line_start(b, j) {
207	                    ml_end = Some(j);
208	                    break;
209	                }
210	                j += 1;
211	            }
212	            if let Some(e) = ml_end {
213	                strings.push(StrLit {
214	                    start: i,
215	                    quote_start: i,
216	                    content_start,
217	                    content_end: e,
218	                    end: e + 1,
219	                    triple: false,
220	                    raw: false,
221	                    bytes: false,
222	                    fstring: false,
223	                    starts_nl: b.get(content_start) == Some(&b'\n'),
224	                    ml: true,
225	                });
226	                i = b[e..].iter().position(|&x| x == b'\n').map(|p| e + p).unwrap_or(b.len());
227	                continue;
228	            }
229	            let mut j = content_start;
230	            let mut close = None;
231	            while j < le {
232	                if b[j] == b'\\' {
233	                    j += 2;
234	                    continue;
235	                }
236	                if b[j] == q {
237	                    close = Some(j);
238	                    break;
239	                }
240	                j += 1;
241	            }
242	            match close {
243	                Some(e) => {
244	                    strings.push(StrLit {
245	                        start: i,
246	                        quote_start: i,
247	                        content_start,
248	                        content_end: e,
249	                        end: e + 1,
250	                        triple: false,
251	                        raw: false,
252	                        bytes: false,
253	                        fstring: false,
254	                        starts_nl: false,
255	                        ml: false,
256	                    });
257	                    i = e + 1;
258	                }
259	                None => i += 1,
260	            }
261	            continue;
262	        }
263	        i += 1;
264	    }
265	    Tokens { strings, comments }
266	}
