643	fn parse_document(text: &str, d: Dialect) -> Result<(Value, Vec<String>, bool), Diagnostic> {
644	    let chars: Vec<char> = text.chars().collect();
645	    let mut p = P { s: &chars, i: 0, d, depth: 0, pending: Vec::new(), any_comment: false };
646	    let label = match d {
647	        Dialect::Json => "JSON",
648	        Dialect::Jsonc => "JSONC",
649	        Dialect::Json5 => "JSON5",
650	    };
651	    let res = (|| -> R<(Value, Vec<String>)> {
652	        p.skip_ws()?;
653	        if p.i >= chars.len() && d == Dialect::Json5 {
654	            return Err((p.i, "Unexpected EOF. Was expecting value.".into()));
655	        }
656	        let v = p.value()?;
657	        p.skip_ws()?;
658	        if p.i < chars.len() {
659	            return Err(match d {
660	                Dialect::Json5 => {
661	                    let c = chars[p.i];
662	                    let kind = if c.is_ascii_digit() || c == '-' || c == '+' || c == '.' {
663	                        "Integer"
664	                    } else if c == '"' || c == '\'' {
665	                        "String"
666	                    } else if c == '{' || c == '[' {
667	                        "Punctuator"
668	                    } else {
669	                        "Name"
670	                    };
671	                    (p.i, format!("Unexpected {} token after value", kind))
672	                }
673	                _ => (p.i, "Text cannot contain more than one JSON value".into()),
674	            });
675	        }
676	        let lead = Vec::new();
677	        Ok((v, lead))
678	    })();
679	    match res {
680	        Ok((v, _)) => {
681	            let trailing = p.take_comments();
682	            Ok((v, trailing, p.any_comment))
683	        }
684	        Err((pos, msg)) => {
685	            let (l, c) = pos_to_line_col(&chars, pos);
686	            Err(Diagnostic { line: l, col: c, msg: format!("invalid {}: {}", label, msg) })
687	        }
688	    }
689	}
