708	pub fn convert(text: &str, path: &str, opts: &Options) -> Result<String, Diagnostic> {
709	    let lower = path.to_ascii_lowercase();
710	    let ext = lower.rsplit('.').next().unwrap_or("");
711	    match ext {
712	        "json" | "jsonc" | "json5" => {
713	            let d = match ext {
714	                "json" => Dialect::Json,
715	                "jsonc" => Dialect::Jsonc,
716	                _ => Dialect::Json5,
717	            };
718	            let (v, trailing, any) = parse_document(text, d)?;
719	            // Leading comments of the root are pending in the first element; handled via block_text.
720	            Ok(project(&v, &trailing, any, &[], opts))
721	        }
722	        "jsonl" | "ndjson" => {
723	            let mut out = String::new();
724	            let body = text.strip_suffix('\n').unwrap_or(text);
725	            if body.is_empty() {
726	                return Err(Diagnostic { line: 1, col: 1, msg: "invalid JSON Lines: records cannot be blank".into() });
727	            }
728	            for (i, line) in body.split('\n').enumerate() {
729	                let line = line.strip_suffix('\r').unwrap_or(line);
730	                if line.trim().is_empty() {
731	                    return Err(Diagnostic { line: i + 1, col: 1, msg: "invalid JSON Lines: records cannot be blank".into() });
732	                }
733	                let (v, _, _) = parse_document(line, Dialect::Json).map_err(|mut d| {
734	                    d.line = i + 1;
735	                    d
736	                })?;
737	                out.push_str("---\n");
738	                out.push_str(&project(&v, &[], false, &[], opts));
739	            }
740	            Ok(out)
741	        }
742	        _ => Err(Diagnostic {
743	            line: 1,
744	            col: 1,
745	            msg: "JSON-to-YAML projection requires a .json, .jsonc, .json5, .jsonl, or .ndjson source path".into(),
746	        }),
747	    }
748	}
