 5	/// Whether any single line of `s` contains a complete template expression.
 6	pub fn contains_template(s: &str, delims: &TemplateDelims) -> bool {
 7	    for line in s.split('\n') {
 8	        for (open, close) in &delims.pairs {
 9	            let mut from = 0;
10	            while let Some(p) = line[from..].find(open.as_str()) {
11	                let after = from + p + open.len();
12	                if line[after..].contains(close.as_str()) {
13	                    return true;
14	                }
15	                from = from + p + 1;
16	                if from >= line.len() {
17	                    break;
18	                }
19	            }
20	        }
21	    }
22	    false
23	}

