 47	/// Directive comment lines outside containers, in document order, as (0-based
 48	/// line, line text). `line0` is the line of the first block.
 49	fn directive_lines(blocks: &[Block], line0: usize, out: &mut Vec<(usize, String)>) {
 50	    let mut line = line0;
 51	    for b in blocks {
 52	        match b {
 53	            Block::Comment(ls) | Block::Para(ls) | Block::Raw(ls) => {
 54	                for (k, l) in ls.iter().enumerate() {
 55	                    if directive_of(l).is_some() {
 56	                        out.push((line + k, l.clone()));
 57	                    }
 58	                }
 59	            }
 60	            Block::Div { inner, .. } => directive_lines(inner, line + 1, out),
 61	            _ => {}
 62	        }
 63	        line += block::line_count(b);
 64	    }
 65	}
