352	/// Format a fragment whose first line is absolute line `line_base` (for notes).
353	pub fn format_fragment_at(text: &str, opts: &Options, notes: &mut Vec<Diagnostic>, line_base: Option<usize>, origin: Option<(usize, usize)>) -> Vec<String> {
354	    let lines = split_lines(text);
355	    if let Some((l0, c0)) = origin {
356	        if let Err(mut d) = check_text_directives(&lines) {
357	            d.line += l0;
