361	            });
362	        }
363	    }
364	    if has_skip_file(&lines) {
365	        return lines;
366	    }
367	    let mut opts = opts.clone();
368	    let mut out: Vec<String> = Vec::new();
369	    let mut body_start = 0;
370	    if let Some(end) = front_matter_end(&lines) {
371	        let yaml_src = if end > 1 { format!("{}\n", lines[1..end].join("\n")) } else { String::new() };
372	        if !yaml_src.is_empty() && crate::yaml::parser::Parser::new(&yaml_src).parse_stream().is_err() {
373	            return lines;
