 14	fn split_lines(text: &str) -> Vec<String> {
 15	    let body = text.strip_suffix('\n').unwrap_or(text);
 16	    if body.is_empty() && text.is_empty() {
 17	        return Vec::new();
 18	    }
 19	    body.split('\n').map(|s| s.to_string()).collect()
 20	}
