 22	/// Option words and scope of an option-only directive comment
 23	/// (`<!-- fmt: wrap=40 scope=from-here -->`); the default scope is the file.
 24	pub fn option_directive(line: &str) -> Option<(Vec<String>, &'static str)> {
 25	    let d = directive_of(line)?;
 26	    let mut words = Vec::new();
 27	    // `markdown` options apply to the next block unless scoped otherwise.
 28	    let (d, mut scope) = match d.strip_prefix("markdown") {
 29	        Some(rest) if rest.is_empty() || rest.starts_with(char::is_whitespace) => (rest.to_string(), "next"),
 30	        _ => (d, "file"),
 31	    };
 32	    for w in d.split_whitespace() {
 33	        match w.strip_prefix("scope=") {
 34	            Some("next") => scope = "next",
 35	            Some("from-here") => scope = "from-here",
 36	            Some(_) => scope = "file",
 37	            None => words.push(w.to_string()),
 38	        }
 39	    }
 40	    let is_option = |w: &String| w.contains('=') || w == "canonical";
 41	    if words.is_empty() || !words.iter().all(is_option) {
 42	        return None;
 43	    }
 44	    Some((words, scope))
 45	}
