 47	/// Directive comment lines outside containers, in document order, as (0-based
 48	/// line, line text). `line0` is the line of the first block.
 49	fn directive_lines(blocks: &[Block], line0: usize, out: &mut Vec<(usize, String)>) {
 50	    let mut line = line0;
 51	    for b in blocks {
 52	        match b {
 53	            Block::Comment(ls) | Block::Para(ls) | Block::Raw(ls) => {
 54	                for (k, l) in ls.iter().enumerate() {
 55	                    if directive_of(l).is_some() {
 56	                        out.push((line + k, l.clone()));
 57	                    }
 58	                }
 59	            }
 60	            Block::Div { inner, .. } => directive_lines(inner, line + 1, out),
 61	            _ => {}
 62	        }
 63	        line += block::line_count(b);
 64	    }
 65	}
 66	
 67	/// Check directive comments in document order, up to a `skip file` directive.
 68	/// The block after a `skip` directive is checked too, `fmt: off` regions are not.
 69	/// `lines` are the source lines from `line0` on.
 70	fn check_directives(blocks: &[Block], lines: &[String], line0: usize) -> Result<bool, Diagnostic> {
 71	    use crate::yaml::directive::{check_markdown, check_option_word, check_toggle, DirKind};
 72	    let mut found = Vec::new();
 73	    for b in blocks {
 74	        match b {
 75	            Block::Verbatim(ls) if directive_of(&ls[0]).is_some_and(|d| d.starts_with("skip")) => {
 76	                directive_lines(&block::parse_blocks(&ls[1..]), 0, &mut found);
 77	            }
 78	            _ => directive_lines(std::slice::from_ref(b), 0, &mut found),
 79	        }
 80	    }
 81	    // Locate the lines in the source, in order.
 82	    let mut next = 0;
 83	    let mut located = Vec::new();
 84	    for (_, l) in found {
 85	        if let Some(k) = lines[next..].iter().position(|s| *s == l) {
 86	            located.push((line0 + next + k, l));
 87	            next += k + 1;
 88	        }
 89	    }
 90	    for (n, l) in located {
 91	        let Some(d) = directive_of(&l) else { continue };
 92	        let col = l[..l.find("fmt:").unwrap_or(0)].chars().count() + 1;
 93	        let words: Vec<&str> = d.split_whitespace().collect();
 94	        let r = match words.first().copied() {
 95	            None => Err("invalid fmt directive: empty".to_string()),
 96	            Some("skip" | "off" | "on") => match check_toggle(&words) {
 97	                Ok(DirKind::SkipFile) => return Ok(true),
 98	                r => r.map(|_| ()),
 99	            },
100	            Some("markdown") => check_markdown(&words[1..]),
101	            Some(w) if w.contains('=') || w == "canonical" => words.iter().try_for_each(|w| check_option_word(w)),
102	            Some(_) => Err(format!("invalid fmt directive: {}", d)),
103	        };
104	        r.map_err(|m| Diagnostic::new(n + 1, col, m))?;
105	    }
106	    Ok(false)
107	}
