109	/// Check the directives of a document unless its front matter is unreadable (the
110	/// document is then kept as written).
111	fn check_text_directives(all: &[String]) -> Result<(), Diagnostic> {
112	    let fm_end = front_matter_end(all);
113	    let fm_ok = fm_end.is_none_or(|end| end <= 1 || crate::yaml::parser::Parser::new(&format!("{}\n", all[1..end].join("\n"))).parse_stream().is_ok());
114	    if fm_ok {
115	        let body_start = fm_end.map_or(0, |e| e + 1);
116	        check_directives(&parse_with_directives(&all[body_start..], None), &all[body_start..], body_start)?;
117	    }
118	    Ok(())
119	}
