121	fn directive_of(line: &str) -> Option<String> {
122	    let t = line.trim();
123	    let inner = t.strip_prefix("<!--")?.strip_suffix("-->")?.trim();
124	    let d = inner.strip_prefix("fmt:")?;
125	    Some(d.trim().to_string())
126	}
