128	/// Find the end of YAML front matter starting at line 0.
129	fn front_matter_end(lines: &[String]) -> Option<usize> {
130	    if lines.is_empty() || lines[0].trim_end() != "---" {
131	        return None;
132	    }
133	    for (i, l) in lines.iter().enumerate().skip(1) {
134	        let t = l.trim_end();
135	        if t == "---" || t == "..." {
136	            return Some(i);
137	        }
138	    }
139	    None
140	}
