142	/// Read editor_options.markdown settings from front matter YAML.
143	fn apply_front_matter_options(yaml: &str, opts: &mut Options) {
144	    let p = crate::yaml::parser::Parser::new(yaml);
145	    let src = yaml;
146	    let stream = match p.parse_stream() {
147	        Ok(s) => s,
148	        Err(_) => return,
149	    };
150	    // Options written after a structurally recovered line are not read.
151	    let recovered = crate::yaml::parser::last_struct_recovery();
152	    let root = match stream.docs.first().and_then(|d| d.root.as_ref()) {
153	        Some(r) => r,
154	        None => return,
155	    };
156	    let find = |n: &crate::yaml::parser::Node, key: &str| -> Option<crate::yaml::parser::Node> {
157	        if let crate::yaml::parser::Kind::Map(entries) = &n.kind {
158	            for e in entries {
159	                let k = &src[e.start..e.key_end];
160	                let k = k.trim_matches(|c| c == '"' || c == '\'');
161	                if k == key {
162	                    return Some(e.value.clone());
163	                }
164	            }
165	        }
166	        if let crate::yaml::parser::Kind::FlowMap(entries) = &n.kind {
167	            for e in entries {
168	                if let Some(k) = &e.key {
169	                    if let crate::yaml::parser::Kind::Scalar(sc) = &k.kind {
170	                        if sc.value == key {
171	                            return e.value.clone();
172	                        }
173	                    }
174	                }
175	            }
176	        }
177	        None
178	    };
179	    let md = match find(root, "editor_options").and_then(|eo| find(&eo, "markdown")) {
180	        Some(m) => Some(m),
181	        None => find(root, "editor").and_then(|e| find(&e, "markdown")),
