221	/// Parse blocks applying top-level preserve directives.
222	fn parse_with_directives(lines: &[String], base: Option<usize>) -> Vec<Block> {
223	    // Split at fmt: off/on regions and fmt: skip targets.
224	    let mut out: Vec<Block> = Vec::new();
225	    let mut seg_start = 0;
226	    let mut i = 0;
227	    let n = lines.len();
228	    let mut in_fence: Option<(char, usize)> = None;
229	    while i < n {
230	        let l = &lines[i];
231	        if let Some((ch, len)) = in_fence {
232	            let t = l.trim();
233	            if block::indent_of(l) <= 3 && t.chars().take_while(|&c| c == ch).count() >= len && t.chars().all(|c| c == ch) {
234	                in_fence = None;
235	            }
236	            i += 1;
237	            continue;
238	        }
239	        if let Some(f) = block::fence_open(l) {
240	            in_fence = Some((f.ch, f.len));
241	            i += 1;
242	            continue;
243	        }
244	        if block::indent_of(l) == 0 {
245	            if let Some(d) = directive_of(l) {
246	                if d == "off" || d == "off scope=from-here" {
247	                    out.extend(block::parse_blocks_at(&lines[seg_start..i], base.map(|b| b + seg_start)));
248	                    let s = i;
249	                    let mut j = i + 1;
250	                    while j < n {
251	                        if directive_of(&lines[j]).as_deref() == Some("on") {
252	                            break;
253	                        }
254	                        j += 1;
255	                    }
256	                    let e = if j < n { j + 1 } else { n };
257	                    out.push(Block::Verbatim(lines[s..e].to_vec()));
258	                    i = e;
259	                    seg_start = e;
260	                    continue;
261	                }
262	                if d == "skip" || d == "skip scope=next" {
263	                    out.extend(block::parse_blocks_at(&lines[seg_start..i], base.map(|b| b + seg_start)));
264	                    let s = i;
265	                    let mut j = i + 1;
266	                    while j < n && block::is_blank(&lines[j]) {
267	                        j += 1;
268	                    }
269	                    // Next block extent: parse from j and take the first block's line span.
270	                    let rest = &lines[j..];
271	                    let span = first_block_span(rest);
272	                    let e = (j + span).min(n);
273	                    out.push(Block::Verbatim(lines[s..e].to_vec()));
274	                    i = e;
275	                    seg_start = e;
276	                    continue;
277	                }
278	            }
279	        }
280	        i += 1;
281	    }
282	    out.extend(block::parse_blocks_at(&lines[seg_start..n], base.map(|b| b + seg_start)));
283	    out
284	}
