286	/// Number of lines spanned by the first block of `lines`.
287	fn first_block_span(lines: &[String]) -> usize {
288	    if lines.is_empty() {
289	        return 0;
290	    }
291	    for k in 1..=lines.len() {
292	        let bs = block::parse_blocks(&lines[..k]);
293	        let full = block::parse_blocks(&lines[..lines.len().min(k + 1)]);
294	        if bs.len() == 1 && full.len() >= 2 {
295	            return k;
296	        }
297	        if full.len() == 1 && k == lines.len() {
298	            return k;
299	        }
300	    }
301	    lines.len()
302	}
