304	fn has_skip_file(lines: &[String]) -> bool {
305	    let mut in_fence: Option<(char, usize)> = None;
306	    for l in lines {
307	        if let Some((ch, len)) = in_fence {
308	            let t = l.trim();
309	            if t.chars().take_while(|&c| c == ch).count() >= len && t.chars().all(|c| c == ch) {
310	                in_fence = None;
311	            }
312	            continue;
313	        }
314	        if let Some(f) = block::fence_open(l) {
315	            in_fence = Some((f.ch, f.len));
316	            continue;
317	        }
318	        if let Some(d) = directive_of(l) {
319	            if d == "skip file" || d == "skip scope=file" {
320	                return true;
321	            }
322	        }
323	    }
324	    false
325	}
