352	/// Format a fragment whose first line is absolute line `line_base` (for notes).
353	pub fn format_fragment_at(text: &str, opts: &Options, notes: &mut Vec<Diagnostic>, line_base: Option<usize>, origin: Option<(usize, usize)>) -> Vec<String> {
354	    let lines = split_lines(text);
355	    if let Some((l0, c0)) = origin {
356	        if let Err(mut d) = check_text_directives(&lines) {
357	            d.line += l0;
358	            d.col += c0;
359	            FRAGMENT_ERROR.with(|e| {
360	                e.borrow_mut().get_or_insert(d);
361	            });
362	        }
363	    }
364	    if has_skip_file(&lines) {
365	        return lines;
366	    }
367	    let mut opts = opts.clone();
368	    let mut out: Vec<String> = Vec::new();
369	    let mut body_start = 0;
370	    if let Some(end) = front_matter_end(&lines) {
371	        let yaml_src = if end > 1 { format!("{}\n", lines[1..end].join("\n")) } else { String::new() };
372	        if !yaml_src.is_empty() && crate::yaml::parser::Parser::new(&yaml_src).parse_stream().is_err() {
373	            return lines;
374	        }
375	        if !opts.ignore_document_options {
376	            apply_front_matter_options(&yaml_src, &mut opts);
377	        }
378	        let formatted = crate::yaml::format_yaml(&yaml_src, &opts).unwrap_or(yaml_src.clone());
379	        out.push(lines[0].trim_end().to_string());
380	        for l in formatted.strip_suffix('\n').unwrap_or(&formatted).split('\n') {
381	            if end > 1 {
382	                out.push(l.to_string());
383	            }
384	        }
385	        out.push(lines[end].trim_end().to_string());
386	        body_start = end + 1;
387	    }
388	    // File-scope option directives apply to the whole document.
389	    let blocks = parse_with_directives(&lines[body_start..], line_base.map(|b| b + body_start));
390	    let mut found = Vec::new();
391	    directive_lines(&blocks, 0, &mut found);
392	    for (_, l) in found {
393	        if let Some((words, "file")) = option_directive(&l) {
394	            crate::yaml::emit::apply_md_words(&mut opts, &words);
395	        }
396	    }
397	    let total = wrap_total(opts.wrap);
398	    let mut f = format::Fmt::new(opts, notes);
399	    f.emit_notes = line_base.is_some() && !f.opts.skip_embedded;
400	    out.extend(f.format_blocks(&blocks, 0, 0, total));
401	    out
402	}
