261	impl Walker {
262	    pub fn new() -> Self {
263	        Walker { stack: Vec::new(), global: global_gitignore(), global_parsed: None }
264	    }
265	
266	    fn is_ignored(&self, path: &Path, is_dir: bool) -> bool {
267	        let any_git = self.stack.iter().any(|d| d.has_git);
268	        let mut m_ignore = Match::None;
269	        let mut m_gi = Match::None;
270	        let mut m_ex = Match::None;
271	        let mut saw_git = false;
272	        for d in self.stack.iter().rev() {
273	            if m_ignore == Match::None {
274	                if let Some(f) = &d.ignore {
275	                    m_ignore = f.matched(path, is_dir);
276	                }
277	            }
278	            if any_git && !saw_git && m_gi == Match::None {
279	                if let Some(f) = &d.gitignore {
280	                    m_gi = f.matched(path, is_dir);
281	                }
282	            }
283	            if any_git && !saw_git && m_ex == Match::None {
284	                if let Some(f) = &d.git_exclude {
285	                    m_ex = f.matched(path, is_dir);
286	                }
287	            }
288	            saw_git = saw_git || d.has_git;
289	            let _ = &d.dir;
290	        }
291	        let mut m = if m_ignore != Match::None {
292	            m_ignore
293	        } else if m_gi != Match::None {
294	            m_gi
295	        } else {
296	            m_ex
297	        };
298	        if m == Match::None && any_git {
299	            if let Some(g) = &self.global_parsed {
300	                if let Some(root) = self.stack.iter().rev().find(|d| d.has_git) {
301	                    let mut g2 = g.clone();
302	                    g2.base = root.dir.clone();
303	                    m = g2.matched(path, is_dir);
304	                }
305	            }
306	        }
307	        m == Match::Ignore
308	    }
309	
310	    /// Walk `root` (a directory), returning files in traversal order.
311	    pub fn walk(&mut self, root: &Path) -> Vec<PathBuf> {
312	        let mut out = Vec::new();
313	        self.stack.clear();
314	        // Ancestors of the root contribute ignore rules.
315	        let abs = fs::canonicalize(root).unwrap_or_else(|_| root.to_path_buf());
316	        let mut ancestors: Vec<PathBuf> = abs.ancestors().skip(1).map(|p| p.to_path_buf()).collect();
317	        ancestors.reverse();
318	        let mut parents = Vec::new();
319	        for a in ancestors {
320	            parents.push(load_dir(&a));
321	        }
322	        // Use absolute paths for matching ancestors; we match with absolute paths throughout.
323	        self.stack = parents;
324	        if let Some(g) = &self.global {
325	            self.global_parsed = Some(parse_ignore(g, Path::new("")));
326	        }
327	        self.walk_dir(root, &abs, &mut out);
328	        out
329	    }
330	
331	    fn walk_dir(&mut self, dir: &Path, abs_dir: &Path, out: &mut Vec<PathBuf>) {
332	        let d = load_dir(abs_dir);
333	        self.stack.push(d);
334	        let mut entries: Vec<(String, PathBuf, bool)> = Vec::new();
335	        if let Ok(rd) = fs::read_dir(dir) {
336	            for e in rd.flatten() {
337	                let name = e.file_name().to_string_lossy().into_owned();
338	                let ft = match e.file_type() {
339	                    Ok(f) => f,
340	                    Err(_) => continue,
341	                };
342	                if ft.is_symlink() {
343	                    continue;
344	                }
345	                entries.push((name, e.path(), ft.is_dir()));
346	            }
347	        }
348	        entries.sort_by(|a, b| a.0.as_bytes().cmp(b.0.as_bytes()));
349	        for (name, path, is_dir) in entries {
350	            if name.starts_with('.') {
351	                continue;
352	            }
353	            let abs_path = abs_dir.join(&name);
354	            if self.is_ignored_global_rel(&abs_path, is_dir) {
355	                continue;
356	            }
357	            if is_dir {
358	                self.walk_dir(&path, &abs_path, out);
359	            } else {
360	                out.push(path);
361	            }
362	        }
363	        self.stack.pop();
364	    }
365	
366	    fn is_ignored_global_rel(&self, abs_path: &Path, is_dir: bool) -> bool {
367	        // Global patterns are matched against the path relative to the repository root.
368	        if self.is_ignored(abs_path, is_dir) {
369	            return true;
370	        }
371	        false
372	    }
373	}
