  1	// Minimal TOML reader for yamark.toml.
  2	
  3	#[derive(Debug, Clone, PartialEq)]
  4	pub enum Value {
  5	    Str(String),
  6	    Int(i64),
  7	    Float(f64),
  8	    Bool(bool),
  9	    Array(Vec<Value>),
 10	    Table(Vec<(String, Value)>),
 11	}
 12	
 13	impl Value {
 14	    pub fn type_name(&self) -> &'static str {
 15	        match self {
 16	            Value::Str(_) => "string",
 17	            Value::Int(_) => "integer",
 18	            Value::Float(_) => "float",
 19	            Value::Bool(_) => "boolean",
 20	            Value::Array(_) => "array",
 21	            Value::Table(_) => "table",
 22	        }
 23	    }
 24	    pub fn get(&self, key: &str) -> Option<&Value> {
 25	        match self {
 26	            Value::Table(t) => t.iter().find(|(k, _)| k == key).map(|(_, v)| v),
 27	            _ => None,
 28	        }
 29	    }
 30	}
 31	
 32	#[derive(Debug)]
 33	pub struct TomlError {
 34	    pub line: usize,
 35	    pub col: usize,
 36	    pub msg: String,
 37	    pub span: usize,
 38	}
 39	
 40	struct P<'a> {
 41	    s: &'a [char],
 42	    i: usize,
 43	}
 44	
 45	type R<T> = Result<T, TomlError>;
 46	
 47	impl<'a> P<'a> {
 48	    fn pos(&self) -> (usize, usize) {
 49	        let mut line = 1;
 50	        let mut col = 1;
 51	        for &c in &self.s[..self.i.min(self.s.len())] {
 52	            if c == '\n' {
 53	                line += 1;
 54	                col = 1;
 55	            } else {
 56	                col += 1;
 57	            }
 58	        }
 59	        (line, col)
 60	    }
 61	    fn err<T>(&self, msg: &str) -> R<T> {
 62	        let (line, col) = self.pos();
 63	        Err(TomlError { line, col, msg: msg.to_string(), span: 1 })
 64	    }
 65	    fn peek(&self) -> Option<char> {
 66	        self.s.get(self.i).copied()
 67	    }
 68	    fn ws(&mut self) {
 69	        while let Some(c) = self.peek() {
 70	            if c == ' ' || c == '\t' {
 71	                self.i += 1;
 72	            } else {
 73	                break;
 74	            }
 75	        }
 76	    }
 77	    fn ws_nl(&mut self) {
 78	        loop {
 79	            self.ws();
 80	            match self.peek() {
 81	                Some('\n') | Some('\r') => self.i += 1,
 82	                Some('#') => {
 83	                    while let Some(c) = self.peek() {
 84	                        if c == '\n' {
 85	                            break;
 86	                        }
 87	                        self.i += 1;
 88	                    }
 89	                }
 90	                _ => break,
 91	            }
 92	        }
 93	    }
 94	    fn line_end(&mut self) -> R<()> {
 95	        self.ws();
 96	        match self.peek() {
 97	            None => Ok(()),
 98	            Some('\n') => {
 99	                self.i += 1;
100	                Ok(())
101	            }
102	            Some('\r') => {
103	                self.i += 1;
104	                if self.peek() == Some('\n') {
105	                    self.i += 1;
106	                }
107	                Ok(())
108	            }
109	            Some('#') => {
110	                while let Some(c) = self.peek() {
111	                    if c == '\n' {
112	                        break;
113	                    }
114	                    self.i += 1;
115	                }
116	                Ok(())
117	            }
118	            _ => self.err("expected newline, `#`"),
119	        }
120	    }
121	    fn key_part(&mut self) -> R<String> {
122	        match self.peek() {
123	            Some('"') => self.basic_string(),
124	            Some('\'') => self.literal_string(),
125	            Some(c) if c.is_ascii_alphanumeric() || c == '_' || c == '-' => {
126	                let s = self.i;
127	                while let Some(c) = self.peek() {
128	                    if c.is_ascii_alphanumeric() || c == '_' || c == '-' {
129	                        self.i += 1;
130	                    } else {
131	                        break;
132	                    }
133	                }
134	                Ok(self.s[s..self.i].iter().collect())
135	            }
136	            _ => self.err("invalid key"),
137	        }
138	    }
139	    fn dotted_key(&mut self) -> R<Vec<String>> {
140	        let mut parts = vec![self.key_part()?];
