161	                    return Ok(out);
162	                }
163	                Some('\\') => {
164	                    self.i += 1;
165	                    let e = self.peek();
166	                    self.i += 1;
167	                    match e {
168	                        Some('n') => out.push('\n'),
169	                        Some('t') => out.push('\t'),
170	                        Some('r') => out.push('\r'),
171	                        Some('"') => out.push('"'),
172	                        Some('\\') => out.push('\\'),
173	                        Some('u') | Some('U') => {
174	                            let n = if e == Some('u') { 4 } else { 8 };
175	                            let h: String = self.s[self.i..(self.i + n).min(self.s.len())].iter().collect();
176	                            self.i += n;
