181	                        }
182	                        _ => return self.err("invalid escape sequence"),
183	                    }
184	                }
185	                Some(c) => {
186	                    out.push(c);
187	                    self.i += 1;
188	                }
189	            }
190	        }
191	    }
192	    fn literal_string(&mut self) -> R<String> {
193	        self.i += 1;
194	        let s = self.i;
195	        loop {
196	            match self.peek() {
197	                None | Some('\n') => return self.err("invalid literal string"),
198	                Some('\'') => {
199	                    let v: String = self.s[s..self.i].iter().collect();
200	                    self.i += 1;
201	                    return Ok(v);
202	                }
203	                _ => self.i += 1,
204	            }
205	        }
206	    }
207	    fn value(&mut self) -> R<Value> {
